from pathlib import Path
import json

p=Path('app/src/main/assets/www/index.html')
s=p.read_text(encoding='utf-8')
rules=json.loads(Path('rules/dzen-rules.json').read_text(encoding='utf-8'))
rules_js=json.dumps(rules,ensure_ascii=False,separators=(',',':'))

def rep(old,new,label):
    global s
    if old not in s:
        raise SystemExit(f'Patch anchor not found: {label}')
    s=s.replace(old,new,1)

rep('<title>Дзен Текст 1.3.5</title>','<title>Дзен Текст 1.4.0</title>','title')

