css_extra='''.analysisSheet{transition:max-height .18s ease,bottom .18s ease,left .18s ease,right .18s ease}.analysisHeader{display:flex;align-items:center;gap:10px}.analysisHeader h2{flex:1;margin:0 0 15px}.analysisCollapse{width:38px;height:38px;border:1px solid var(--border);border-radius:10px;background:var(--surface2);color:var(--text);font-size:22px;display:grid;place-items:center;margin-bottom:12px}.analysisFilters{display:flex;gap:6px;margin:0 0 12px;overflow-x:auto;scrollbar-width:none}.analysisFilters::-webkit-scrollbar{display:none}.analysisFilter{border:1px solid var(--border);background:var(--surface2);color:var(--text);border-radius:999px;padding:7px 11px;font-size:12px;font-weight:700;white-space:nowrap}.analysisFilter.active{border-color:var(--accent);background:var(--accentSoft);color:var(--accent)}.analysisCollapsedSummary{display:none;color:var(--muted);font-size:12px;line-height:1.35;margin-top:-8px}.sheetBackdrop.collapsed{background:transparent;pointer-events:none}.sheetBackdrop.collapsed .analysisSheet{left:10px;right:10px;bottom:68px;border-radius:16px;max-height:none;padding:11px 13px;pointer-events:auto;box-shadow:0 8px 28px rgba(0,0,0,.2)}.sheetBackdrop.collapsed .analysisSheet>.handle,.sheetBackdrop.collapsed .analysisFilters,.sheetBackdrop.collapsed #analysisBody{display:none}.sheetBackdrop.collapsed .analysisHeader h2{font-size:15px;margin:0}.sheetBackdrop.collapsed .analysisCollapse{margin:0;width:34px;height:34px}.sheetBackdrop.collapsed .analysisCollapsedSummary{display:block;margin:3px 44px 0 0}.analysisRow.dzenRisk .warn{color:#b26718}.analysisDzenNote{background:var(--surface2);border-radius:11px;padding:10px 11px;color:var(--muted);font-size:12px;line-height:1.45;margin:8px 0}.analysisDzenNote b{color:var(--text)}.manualChecklist{margin:7px 0 0;padding-left:18px}.manualChecklist li{margin:5px 0}.ruleStatus{font-size:12px;line-height:1.45;color:var(--muted);margin:8px 0}.ruleStatus b{color:var(--text)}\n'''
