analysis_old='''<div class="sheetBackdrop" id="analysisBackdrop" onclick="analysisBackdropClick(event)"><div class="sheet">\n  <div class="handle"></div><h2>Редакторский анализ</h2><div id="analysisSummary" class="analysisSummary"></div><div id="analysisContent"></div>\n</div></div>'''
